// Battery maintenance settings
// 213: Battery control mode (0=voltage, 1=capacity, 2=no battery)
// 214: Lithium battery wake up (0=enabled, 1=disabled)
// 215: Battery resistance (mΩ)
// 216: Charge efficiency (0.1%)

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 213,
    quantity: 4
};

return msg;

// Build BatteryMaintenanceConfigState from Modbus read.
//
// Registers:
// 213: Battery control mode (0=voltage, 1=capacity, 2=no battery)
// 214: Lithium battery wake up (0=enabled, 1=disabled)
// 215: Battery resistance (mΩ)
// 216: Charge efficiency (0.1%)

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

const controlModeRaw = data[0];      // 213
const wakeUpRaw = data[1];           // 214
const resistanceRaw = data[2];       // 215
const efficiencyRaw = data[3];       // 216

// Map control mode
let batteryControlMode = null;
if (controlModeRaw === 0) {
    batteryControlMode = "voltage";
} else if (controlModeRaw === 1) {
    batteryControlMode = "capacity";
} else if (controlModeRaw === 2) {
    batteryControlMode = null;  // no battery
}

// Wake up: 0=enabled, 1=disabled (inverted logic)
const channel1Enabled = wakeUpRaw === 0;

// Efficiency: 0.1% scale
const chargeEfficiency = efficiencyRaw !== undefined ? 
    Math.round(efficiencyRaw * 0.1 * 10) / 10 : null;

// Resolve identifiers
const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "BatteryMaintenanceConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,
    version: "1",

    batteryControlMode: batteryControlMode,

    wakeUp: {
        channel1Enabled: channel1Enabled,
        channel2Enabled: null  // Reserved for future use
    },

    batteryResistanceMilliOhm: resistanceRaw || null,
    chargeEfficiencyPercent: chargeEfficiency
};

// Keep snapshot in flow
flow.set("batteryMaintenanceConfigSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
